package com.example.orders.entity;import javax.persistence.*;import java.util.Date;@Entity @Table(name="outbox_event",indexes={@Index(name="idx_outbox_status_id",columnList="status,id")}) public class OutboxEvent{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="aggregate_id",nullable=false)private String aggregateId;@Column(name="event_type",nullable=false)private String eventType;@Lob @Column(nullable=false,columnDefinition="LONGTEXT")private String payload;@Column(nullable=false)private String status;@Column(name="retry_count",nullable=false)private int retryCount;@Temporal(TemporalType.TIMESTAMP)@Column(name="created_at",nullable=false)private Date createdAt;@Temporal(TemporalType.TIMESTAMP)@Column(name="locked_at")private Date lockedAt;@Temporal(TemporalType.TIMESTAMP)@Column(name="published_at")private Date publishedAt;public Long getId(){return id;}public void setId(Long v){id=v;}public String getAggregateId(){return aggregateId;}public void setAggregateId(String v){aggregateId=v;}public String getEventType(){return eventType;}public void setEventType(String v){eventType=v;}public String getPayload(){return payload;}public void setPayload(String v){payload=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public int getRetryCount(){return retryCount;}public void setRetryCount(int v){retryCount=v;}public Date getCreatedAt(){return createdAt;}public void setCreatedAt(Date v){createdAt=v;}public Date getLockedAt(){return lockedAt;}public void setLockedAt(Date v){lockedAt=v;}public Date getPublishedAt(){return publishedAt;}public void setPublishedAt(Date v){publishedAt=v;}}